// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Iterator;
import java.util.zip.CRC32C;
import java.util.zip.GZIPOutputStream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalSelectiveReaderTest {

	@TempDir
	Path directory;

	@Test
	void matchesReorderedFieldsInPlainAndCompressedSegments() throws Exception {
		for (boolean compressed : new boolean[] { false, true }) {
			Path walDirectory = Files.createDirectory(directory.resolve(compressed ? "gzip" : "plain"));
			Path segment = walDirectory.resolve(compressed ? "wal-1.v1.gz" : "wal-1.v1");
			try (OutputStream file = Files.newOutputStream(segment);
					OutputStream output = compressed ? new GZIPOutputStream(file) : file) {
				writeFrame(output, "{\"t\":\"V\",\"segment\":1,\"firstId\":1}", false);
				writeFrame(output, "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"skip\"}", false);
				writeFrame(output,
						"{\"lex\":\"chosen\",\"dt\":\"urn:type\",\"lang\":\"\",\"vk\":\"L\",\"lsn\":2,\"id\":2,\"t\":\"M\"}",
						false);
			}
			ValueStoreWalConfig config = config(walDirectory);
			try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
				Iterator<ValueStoreWalRecord> selected = reader.iteratorForId(2);
				assertThat(selected.hasNext()).isTrue();
				ValueStoreWalRecord record = selected.next();
				assertThat(record.id()).isEqualTo(2);
				assertThat(record.lexical()).isEqualTo("chosen");
				assertThat(record.datatype()).isEqualTo("urn:type");
				assertThat(selected.hasNext()).isFalse();
			}
		}
	}

	@Test
	void selectsTheFinalIdWhenAFieldIsRepeated() throws Exception {
		try (OutputStream output = Files.newOutputStream(directory.resolve("wal-1.v1"))) {
			writeFrame(output, "{\"t\":\"V\",\"segment\":1,\"firstId\":1}", false);
			writeFrame(output,
					"{\"t\":\"M\",\"lsn\":1,\"id\":9,\"vk\":\"B\",\"lex\":\"chosen\",\"id\":1}", false);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config(directory))) {
			Iterator<ValueStoreWalRecord> selected = reader.iteratorForId(1);
			assertThat(selected.hasNext()).isTrue();
			assertThat(selected.next().lexical()).isEqualTo("chosen");
			assertThat(selected.hasNext()).isFalse();
			assertThat(reader.isComplete()).isTrue();
		}
	}

	@Test
	void doesNotSkipChecksumValidationOfUnselectedRecords() throws Exception {
		try (OutputStream output = Files.newOutputStream(directory.resolve("wal-1.v1"))) {
			writeFrame(output, "{\"t\":\"V\",\"segment\":1,\"firstId\":1}", false);
			writeFrame(output, "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"bad\"}", true);
			writeFrame(output, "{\"t\":\"M\",\"lsn\":2,\"id\":2,\"vk\":\"B\",\"lex\":\"chosen\"}", false);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config(directory))) {
			assertThat(reader.iteratorForId(2).hasNext()).isFalse();
			assertThat(reader.isComplete()).isFalse();
		}
	}

	private static ValueStoreWalConfig config(Path walDirectory) {
		return ValueStoreWalConfig.builder().walDirectory(walDirectory).storeUuid("selective-reader").build();
	}

	private static void writeFrame(OutputStream output, String json, boolean corruptChecksum) throws Exception {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		ByteArrayOutputStream frame = new ByteArrayOutputStream();
		writeIntLE(frame, bytes.length);
		frame.writeBytes(bytes);
		writeIntLE(frame, (int) crc.getValue() ^ (corruptChecksum ? 1 : 0));
		output.write(frame.toByteArray());
	}

	private static void writeIntLE(OutputStream output, int value) throws Exception {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
